import java.awt.*;import java.awt.font.*;import java.awt.geom.*;
public class Glyphs{
 public static void main(String[]args){System.out.print("export const glyphs={");for(int style:new int[]{Font.PLAIN,Font.BOLD}){var font=org.icpc.tools.presentation.contest.internal.ICPCFont.deriveFont(style,1000);var frc=new FontRenderContext(null,true,true);System.out.print("\""+style+"\":{");for(int c=32;c<256;c++){if(c>=127&&c<160)continue;var vector=font.createGlyphVector(frc,new char[]{(char)c});var shape=vector.getGlyphOutline(0);var iter=shape.getPathIterator(null);double[] xy=new double[6];StringBuilder p=new StringBuilder();while(!iter.isDone()){int t=iter.currentSegment(xy),n=t==0||t==1?2:t==2?4:t==3?6:0;p.append(t==0?'M':t==1?'L':t==2?'Q':t==3?'C':'Z');for(int i=0;i<n;i++){if(i>0)p.append(' ');p.append(Math.round(xy[i]*1000)/1000.0);}iter.next();}System.out.print("\""+c+"\":{\"advance\":"+vector.getGlyphMetrics(0).getAdvance()+",\"path\":\""+p+"\"},");}System.out.print("},");}System.out.print("};\n");}
}
